function debounce(func, delay) {
    let timer = null;
    return function(...args) {
        if (timer) {
            clearTimeout(timer);
        }
        timer = setTimeout(() => {
            func.apply(this, args);
        }, delay);
    };
}

关键点：
1. 需要维护一个定时器标识符，用于清除上一次未执行的函数。
2. 清除定时器时要确保只清除当前未执行的定时器。
3. 确保返回的函数能正确绑定上下文并传递参数。

function throttle(func, delay) {
    let lastCall = 0;
    return function(...args) {
        const now = new Date().getTime();
        if (now - lastCall >= delay) {
            lastCall = now;
            func.apply(this, args);
        }
    }
}

