    virtual ~Base() {}  // 声明为virtual
};

class Derived : public Base {
public:
    ~Derived() {}  // 子类析构函数
};

void func() {
    Base* ptr = new Derived();
    delete ptr;  // 如果Base的析构函数不是virtual，Derived的析构函数不会被调用
}
